const initState = {
    themeId: 1,
}

export type InitialState = typeof initState

export const themeReducer = (state: InitialState = initState, action: ActionType): InitialState => { // fix any
    switch (action.type) {
        // дописать
        case 'SET_THEME_ID': {
            return {...state, themeId: action.id}
        }

        default:
            return state
    }
}

export const changeThemeId = (id: number) => ({ type: 'SET_THEME_ID' as const, id }) // fix any

export type ActionType = ReturnType<typeof changeThemeId>